mkdir -p /workspace/tmp/tests && cat > /workspace/tmp/runner.py << 'EOF'
import json, subprocess, sys, os

MAIN = "/workspace/submission/main.py"

def run_raw(data, expect_rc):
    p = subprocess.run([sys.executable, "-I", MAIN], input=data,
                       capture_output=True)
    if p.returncode != expect_rc:
        return ("RC", p.returncode, expect_rc, p.stderr.decode()[:500])
    return p.stdout

def run_ok(obj):
    data = obj if isinstance(obj, (bytes, bytearray)) else json.dumps(obj).encode()
    out = run_raw(data, 0)
    if isinstance(out, tuple):
        return out
    try:
        return json.loads(out)
    except Exception as e:
        return ("BADJSON", str(e), out[:300])

def run_invalid(data):
    if isinstance(data, (dict, list)):
        data = json.dumps(data).encode()
    out = run_raw(data, 2)
    if isinstance(out, tuple):
        return out
    try:
        o = json.loads(out)
        if o == {"error": "invalid-input"}:
            return "OK-INVALID"
        return ("WRONG-BODY", o)
    except Exception as e:
        return ("BADJSON", str(e), out[:300])

def base(n=2, capacity=None, edges=None, rounds=None):
    return {
        "version": 1,
        "n": n,
        "capacity": capacity if capacity is not None else [2]*n,
        "edges": edges if edges is not None else [],
        "rounds": rounds if rounds is not None else [],
    }

def edge(u,v,ping=1,ack=1,label="a"):
    return {"u":u,"v":v,"ping_us":ping,"ack_us":ack,"label":label}

def rnd(launch=0, timeout=20, host_delay=1, drop_host_ack=False, drop_ping=(), drop_ack=()):
    return {"launch_us":launch,"timeout_us":timeout,"host_delay_us":host_delay,
            "drop_host_ack":drop_host_ack,"drop_ping":list(drop_ping),
            "drop_ack":list(drop_ack)}
EOF
